import{_ as o,a0 as i,w as a,s as r,ao as p,I as n,a1 as u,A as m,x as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"游戏玩家的福音：在 Ubuntu 上安装开源 VoIP 应用 Mumble | LCTT x X-CMD","titleTemplate":false,"description":"游戏玩家的福音：在 Ubuntu 上安装开源 VoIP 应用 Mumble | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"游戏玩家的福音：在 Ubuntu 上安装开源 VoIP 应用 Mumble | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"游戏玩家的福音：在 Ubuntu 上安装开源 VoIP 应用 Mumble | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150211 Install Mumble in Ubuntu an Opensource VoIP Apps","title":"游戏玩家的福音：在 Ubuntu 上安装开源 VoIP 应用 Mumble","tag":"201504","desc":""},"relativePath":"201504/20150211 Install Mumble in Ubuntu an Opensource VoIP Apps.md","filePath":"[post].md"}'),b={name:"201504/20150211 Install Mumble in Ubuntu an Opensource VoIP Apps.md"};function s(d,e,g,x,T,f){const t=i("Link");return a(),r("div",null,[e[15]||(e[15]=p('<h1 id="游戏玩家的福音-在-ubuntu-上安装开源-voip-应用-mumble" tabindex="-1">游戏玩家的福音：在 Ubuntu 上安装开源 VoIP 应用 Mumble <a class="header-anchor" href="#游戏玩家的福音-在-ubuntu-上安装开源-voip-应用-mumble" aria-label="Permalink to “游戏玩家的福音：在 Ubuntu 上安装开源 VoIP 应用 Mumble”">​</a></h1><p>Mumble是一个自由开源的VoIP应用，在新的 BSD 许可证下发布，主要面向的用户群体是游戏玩家。运行起来类似于TeamSpeak和Ventrilo，用户通过连接到同一个服务器来实现相互通讯。</p><p>Mumble提供了如下的漂亮特性:</p><ul><li>低延迟，这点对游戏相当重要</li><li>提供游戏中的可视插件，通过它你可以知道是谁正在和你通话并定位他们的位置</li><li>交谈内容经过加密的，能够保护你的隐私和安全</li><li>界面简单易于上手</li><li>稳定高效的使用你的服务器资源</li></ul><h3 id="安装-mumble" tabindex="-1">安装 Mumble <a class="header-anchor" href="#安装-mumble" aria-label="Permalink to “安装 Mumble”">​</a></h3>',5)),n("p",null,[u(t,{href:"http://wiki.mumble.info/wiki/Main_Page"},{default:m(()=>[...e[0]||(e[0]=[l("Mumble",-1)])]),_:1}),e[1]||(e[1]=l("已经流行开来，进入了许多linux主流发行版的软件仓库，这使它安装起来更加的方便。若你使用的是Ubuntu那么使用apt-get就能安装，详细命令如下：",-1))]),e[16]||(e[16]=p(`<pre><code>$ sudo apt-get install mumble-server
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-install.jpg" alt="mumble install"></p><p>这条命令将会在你的服务器上安装服务端（亦称Murmur）。</p><h3 id="配置-mumble" tabindex="-1">配置 Mumble <a class="header-anchor" href="#配置-mumble" aria-label="Permalink to “配置 Mumble”">​</a></h3><p>运行以下命令启动Mumble：</p><pre><code>$ sudo dpkg-reconfigure mumble-server
</code></pre><p>会弹出以下一些问题：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-q1.jpg" alt="mumble q1"></p><p>选择“是”让服务器开机时自动启动mumble，接着它会询问你是否运行高优先级模式以保持低延迟，为了让它保持最佳性能这是个不错的主意。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-q2.jpg" alt="mumble q2"></p><p>接着为你刚安装好的mumble服务端设管理员用户的密码，记住这个密码，它会在登录时用到。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-q3.jpg" alt="mumble q3"></p><h3 id="安装-mumble-客户端" tabindex="-1">安装 Mumble 客户端 <a class="header-anchor" href="#安装-mumble-客户端" aria-label="Permalink to “安装 Mumble 客户端”">​</a></h3><p>客户端可以安装到许多的主流操作系统中，例如windows，mac和linux。我们将教你在Ubuntu linux上安装和配置，你可以使用软件中心也可以用命令安装客户端：</p><pre><code>$ sudo apt-get install mumble
</code></pre><p>第一次运行mumble时，配置向导将会帮助你配置音频的输入输出，使其能在客户端上保持最好的效果。第一次同样也会询问你要使用的是什么声音设备和麦克风：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-client-1.jpg" alt="mumble client 1"></p><p>然后它将帮你校准设备：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-client-2.jpg" alt="mumble client 2"></p><p>因为mumble会帮你加密所有的通讯内容所以它会要求你创建证书：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-client-3.jpg" alt="mumble client 3"></p><p>完成配置向导后你就能添加第一个服务器，连接对话框如下图所示：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-add-server.jpg" alt="mumble add server"></p><p>首先输入一个标签，名字任意因为那只不过是为了记住服务器的，然后输入服务器的地址和端口，最后使用“SuperUser”作为用户名，而密码则是你配置mumble服务器端时输入的密码。</p><p>现在你可以连接到服务器了，在联网玩游戏或与你好友、队友聊天开黑时享受这些功能给你带来的乐趣吧！</p><hr>`,26)),n("p",null,[e[3]||(e[3]=l("via: ",-1)),u(t,{href:"http://linoxide.com/ubuntu-how-to/install-mumble-ubuntu/"},{default:m(()=>[...e[2]||(e[2]=[l("http://linoxide.com/ubuntu-how-to/install-mumble-ubuntu/",-1)])]),_:1})]),n("p",null,[e[7]||(e[7]=l("作者：",-1)),u(t,{href:"http://linoxide.com/author/adriand/"},{default:m(()=>[...e[4]||(e[4]=[l("Adrian Dinu",-1)])]),_:1}),e[8]||(e[8]=l(" 译者：",-1)),u(t,{href:"https://github.com/martin2011qi"},{default:m(()=>[...e[5]||(e[5]=[l("martin2011qi",-1)])]),_:1}),e[9]||(e[9]=l(" 校对：",-1)),u(t,{href:"https://github.com/wxy"},{default:m(()=>[...e[6]||(e[6]=[l("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=l("本文由 ",-1)),u(t,{href:"https://github.com/LCTT/TranslateProject"},{default:m(()=>[...e[10]||(e[10]=[l("LCTT",-1)])]),_:1}),e[13]||(e[13]=l(" 原创翻译，",-1)),u(t,{href:"http://linux.cn/"},{default:m(()=>[...e[11]||(e[11]=[l("Linux中国",-1)])]),_:1}),e[14]||(e[14]=l(" 荣誉推出",-1))])])}const I=o(b,[["render",s]]);export{h as __pageData,I as default};
